properties.query:
let knownPorts = dynamic([5760, 5790, 14550, 14551]);
let alertWindow = 10m;
let KnownGCS = _GetWatchlist('C2_Whitelisted_GCS_List') | project GCS_IP;
let UnknownConn =
    UAVDatalinkConn_CL
    | where TimeGenerated > ago(alertWindow)
    | where PeerIp !in (KnownGCS)
    | where LocalPort in (knownPorts)
    | summarize ConnCount=count(), FirstSeen=min(TimeGenerated) by PeerIp, LocalPort, State;
let TxAnomaly =
    UAVDatalink_CL
    | where TimeGenerated > ago(24h)
    | make-series AvgTx=avg(TxBytes) on TimeGenerated step 5m by ContainerName
    | extend (Anom, Score, Base) = series_decompose_anomalies(AvgTx, 3.0)
    | mv-expand TimeGenerated, AvgTx=todouble(AvgTx), Anom=toint(Anom)
    | where TimeGenerated > ago(alertWindow) and Anom == 1
    | project T_tx=todatetime(TimeGenerated), ContainerName, AvgTx;
UnknownConn
| join kind=inner (TxAnomaly) on $left.FirstSeen <= $right.T_tx
| extend TriggerReason = strcat("비인가IP_C2포트_TxBurst_PeerIp:", PeerIp, "_Port:", tostring(LocalPort))
| extend Severity = "High"
| project FirstSeen, PeerIp, LocalPort, ConnCount, AvgTx, TriggerReason, Severity
| order by FirstSeen desc
